package dev.aarongame.gcl;

import com.google.gson.*;
import javax.swing.*;
import javax.swing.border.*;
import java.awt.*;
import java.awt.event.*;
import java.awt.geom.*;
import java.nio.file.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.*;
import java.util.function.*;

public final class Launcher {
    final Core core;
    final JFrame frame=new JFrame("GCL · "+Core.VERSION);
    final JPanel content=new JPanel(new BorderLayout(0,18));
    final JLabel status=new JLabel("准备就绪 · 你的世界，由你定义。");
    final JComboBox<Core.Instance> instances=new JComboBox<>();
    final JTextField player=new JTextField("Player");
    final JSpinner ram=new JSpinner(new SpinnerNumberModel(4096,1024,32768,512)),width=new JSpinner(new SpinnerNumberModel(1280,640,7680,160)),height=new JSpinner(new SpinnerNumberModel(720,360,4320,90));
    final ExecutorService worker=Executors.newSingleThreadExecutor();
    final Properties preferences=new Properties();
    volatile Future<?> job; volatile boolean busy;
    String page="开始游戏";
    interface Work {void run()throws Exception;}
    public Launcher()throws Exception{
        core=new Core(Core.defaultRoot(),Core.Platform.detect());
        Path prefs=core.root.resolve("launcher.properties");if(Files.exists(prefs))try(var in=Files.newInputStream(prefs)){preferences.load(in);}
        player.setText(preferences.getProperty("player","Player"));
        UIManager.put("Button.arc",18);UIManager.put("Label.foreground",new Color(26,57,56));
        frame.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);frame.setMinimumSize(new Dimension(1000,740));frame.setSize(1120,800);frame.setLocationRelativeTo(null);
        frame.setIconImage(appImage(64));
        frame.addWindowListener(new WindowAdapter(){public void windowClosed(WindowEvent e){if(job!=null)job.cancel(true);core.stop();worker.shutdownNow();}});
        Glass background=new Glass(false);background.setLayout(new BorderLayout(24,0));background.setBorder(new EmptyBorder(22,22,22,22));frame.setContentPane(background);
        Glass sidebar=new Glass(true);sidebar.setLayout(new BorderLayout(0,24));sidebar.setPreferredSize(new Dimension(195,600));sidebar.setBorder(new EmptyBorder(20,15,20,15));
        JLabel brand=new JLabel("GCL",appIcon(42),SwingConstants.LEFT);brand.setFont(brand.getFont().deriveFont(Font.BOLD,26));brand.setIconTextGap(12);sidebar.add(brand,BorderLayout.NORTH);
        JPanel nav=transparent();nav.setLayout(new BoxLayout(nav,BoxLayout.Y_AXIS));String[] pages={"开始游戏","版本管理","模组管理","资源下载","任务与日志","启动设置","关于 GCL"};String[] icons={"play","versions","mod","download","logs","settings","info"};
        for(int n=0;n<pages.length;n++){String target=pages[n];JButton b=button(target,icons[n],()->show(target));b.setAlignmentX(Component.LEFT_ALIGNMENT);b.setMaximumSize(new Dimension(180,53));nav.add(b);nav.add(Box.createVerticalStrut(9));}sidebar.add(nav,BorderLayout.CENTER);JLabel label=new JLabel(Core.VERSION+" · "+core.platform.os());label.setForeground(new Color(83,114,112));sidebar.add(label,BorderLayout.SOUTH);background.add(sidebar,BorderLayout.WEST);
        JPanel right=transparent();right.setLayout(new BorderLayout(0,18));content.setOpaque(false);right.add(content,BorderLayout.CENTER);Glass footer=new Glass(true);footer.setLayout(new BorderLayout(12,0));footer.setBorder(new EmptyBorder(14,18,14,18));footer.add(status);footer.add(button("停止","stop",()->{if(job!=null)job.cancel(true);core.stop();}),BorderLayout.EAST);right.add(footer,BorderLayout.SOUTH);background.add(right);
        instances.addActionListener(e->{loadSettings();show(page);});reload();show(page);frame.setVisible(true);
    }
    static Image appImage(int size){try{var url=Launcher.class.getResource("/GCL.png");if(url!=null)return new ImageIcon(url).getImage().getScaledInstance(size,size,Image.SCALE_SMOOTH);}catch(Exception ignored){}return new Glyph("grass",size).image();}
    static Icon appIcon(int size){return new ImageIcon(appImage(size));}
    static JPanel transparent(){JPanel p=new JPanel();p.setOpaque(false);return p;}
    static JButton button(String text,String glyph,Runnable action){JButton b=new JButton(text,new Glyph(glyph,25));b.setHorizontalAlignment(SwingConstants.LEFT);b.setIconTextGap(10);b.setFocusPainted(false);b.setBorder(new EmptyBorder(12,14,12,14));b.setBackground(new Color(242,252,251,210));b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));b.addActionListener(e->action.run());return b;}
    void message(String text){SwingUtilities.invokeLater(()->status.setText(text));}
    void run(Work work){if(busy){message("请等待当前操作完成，或先停止");return;}busy=true;job=worker.submit(()->{try{work.run();}catch(InterruptedException e){message("已取消");}catch(Exception e){message("操作失败："+(e.getCause()==null?e.getMessage():e.getCause().getMessage()));}finally{busy=false;}});}
    Core.Instance selected(){return (Core.Instance)instances.getSelectedItem();}
    void reload()throws Exception{Core.Instance old=selected();instances.removeAllItems();for(Core.Instance i:core.instances())instances.addItem(i);if(old!=null)for(int n=0;n<instances.getItemCount();n++)if(instances.getItemAt(n).id().equals(old.id()))instances.setSelectedIndex(n);}
    void open(Path dir){try{Files.createDirectories(dir);Desktop.getDesktop().open(dir.toFile());}catch(Exception e){message(e.getMessage());}}
    String setting(String key,String fallback){Core.Instance i=selected();return preferences.getProperty((i==null?"default":i.id())+"."+key,fallback);}
    void loadSettings(){try{ram.setValue(Integer.parseInt(setting("ram","4096")));width.setValue(Integer.parseInt(setting("width","1280")));height.setValue(Integer.parseInt(setting("height","720")));}catch(NumberFormatException ignored){}}
    void saveSettings()throws Exception{preferences.setProperty("player",player.getText());for(var e:Map.of("ram",ram,"width",width,"height",height).entrySet())preferences.setProperty((selected()==null?"default":selected().id())+"."+e.getKey(),e.getValue().getValue().toString());try(var out=Files.newOutputStream(core.root.resolve("launcher.properties"))){preferences.store(out,"GCL local preferences");}}
    Glass card(){Glass p=new Glass(true);p.setBorder(new EmptyBorder(22,24,22,24));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));return p;}
    void line(JPanel parent,String text){JLabel l=new JLabel("<html><div style='width:540px;line-height:1.7'>"+escape(text)+"</div></html>");l.setAlignmentX(Component.LEFT_ALIGNMENT);parent.add(l);parent.add(Box.createVerticalStrut(15));}
    static String escape(String text){return text.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
    void row(JPanel panel,String title,JComponent field){JPanel p=transparent();p.setLayout(new BorderLayout(20,0));p.add(new JLabel(title),BorderLayout.WEST);p.add(field);p.setMaximumSize(new Dimension(850,44));p.setAlignmentX(Component.LEFT_ALIGNMENT);panel.add(p);panel.add(Box.createVerticalStrut(16));}
    void show(String next){page=next;content.removeAll();JLabel title=new JLabel(next,next.equals("开始游戏")?appIcon(48):new Glyph("versions",42),SwingConstants.LEFT);title.setFont(title.getFont().deriveFont(Font.BOLD,30));title.setIconTextGap(14);content.add(title,BorderLayout.NORTH);
        JPanel body=transparent();body.setLayout(new BoxLayout(body,BoxLayout.Y_AXIS));Glass config=card();row(config,"当前实例",instances);row(config,"本地用户名",player);body.add(config);body.add(Box.createVerticalStrut(18));Glass card=card();body.add(card);
        switch(next){case "开始游戏"->home(card);case "版本管理"->library(card);case "模组管理"->mods(card);case "资源下载"->resources(card);case "任务与日志"->logs(card);case "启动设置"->settings(card);default->{line(card,"GCL · GlassCraft Launcher "+Core.VERSION);line(card,"Windows / Linux 跨平台 Java 桌面版。采用系统桌面控件；Apple Liquid Glass 仅在原生 Mac / iOS 版提供。当前提供原版、Fabric、Quilt、Java 下载与本地模组管理。");line(card,"本地模式不能使用 Realms 或要求正版验证的服务器。完整进入世界尚未验证；旧版、ARM 原生库和不同发行版可能存在兼容限制。");card.add(button("开源与贡献者","info",()->{try{Desktop.getDesktop().browse(java.net.URI.create("https://github.com/Aaron-CNSD/GCL"));}catch(Exception ex){message(ex.getMessage());}}));}}
        body.add(Box.createVerticalGlue());JScrollPane scroll=new JScrollPane(body);scroll.setOpaque(false);scroll.getViewport().setOpaque(false);scroll.setBorder(null);scroll.getVerticalScrollBar().setUnitIncrement(20);content.add(scroll);content.revalidate();content.repaint();
    }
    void home(JPanel p){line(p,"你的世界，由你定义。选择实例后，GCL 会下载游戏文件和匹配的 Java。");row(p,"运行内存 MB",ram);p.add(button("下载并启动","play",()->{Core.Instance i=selected();if(i==null){message("请先在版本管理中新建一个实例");return;}String name=player.getText();int memory=(Integer)ram.getValue(),w=(Integer)width.getValue(),h=(Integer)height.getValue();try{saveSettings();}catch(Exception e){message(e.getMessage());return;}run(()->core.launch(i,name,memory,w,h,this::message));}));p.add(Box.createVerticalStrut(14));p.add(button("打开游戏目录","folder",()->{if(selected()!=null)open(core.gameDir(selected()));}));}
    void library(JPanel p){line(p,"每个实例拥有独立的模组、配置和存档目录。旧版游戏需要匹配的原生库。");p.add(button("新建游戏实例","versions",this::create));p.add(Box.createVerticalStrut(15));p.add(button("刷新配置列表","versions",()->{try{reload();message("配置列表已刷新");}catch(Exception e){message(e.getMessage());}}));}
    void create(){JTextField name=new JTextField("新的世界");JComboBox<String> game=new JComboBox<>(new String[]{"1.21.1","1.20.1","1.16.5","1.12.2","1.7.10"}),loader=new JComboBox<>(new String[]{"原版","Fabric","Quilt"}),build=new JComboBox<>();JPanel form=new JPanel(new GridLayout(0,2,14,14));form.add(new JLabel("名称"));form.add(name);form.add(new JLabel("Minecraft"));form.add(game);form.add(new JLabel("加载器"));form.add(loader);form.add(new JLabel("加载器版本"));form.add(build);
        Runnable refresh=()->{String g=(String)game.getSelectedItem(),l=(String)loader.getSelectedItem();build.removeAllItems();if(l.equals("原版"))return;run(()->{List<String> versions=core.loaders(g,l);SwingUtilities.invokeLater(()->{if(g.equals(game.getSelectedItem())&&l.equals(loader.getSelectedItem()))for(String v:versions)build.addItem(v);});});};loader.addActionListener(e->refresh.run());game.addActionListener(e->refresh.run());
        run(()->{List<String> versions=core.versions();SwingUtilities.invokeLater(()->{String old=(String)game.getSelectedItem();game.setModel(new DefaultComboBoxModel<>(versions.toArray(String[]::new)));game.setSelectedItem(old);});});
        if(JOptionPane.showConfirmDialog(frame,form,"新建独立实例",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){String g=(String)game.getSelectedItem(),l=(String)loader.getSelectedItem(),b=(String)build.getSelectedItem(),n=name.getText();run(()->{Core.Instance i=core.create(n,g,l,b==null?"":b);SwingUtilities.invokeLater(()->{try{reload();instances.setSelectedItem(i);message("实例已创建，首次启动会下载游戏");}catch(Exception e){message(e.getMessage());}});});}}
    void mods(JPanel p){Core.Instance i=selected();if(i==null){line(p,"请先选择一个实例。");return;}line(p,"模组启停保留原文件；停用时追加 .disabled。额外依赖需另行安装。");try{for(Path mod:core.mods(i)){JButton b=button((mod.toString().endsWith(".disabled")?"启用 · ":"停用 · ")+mod.getFileName(),"mod",()->{if(busy){message("请先停止游戏或当前任务");return;}try{core.toggle(i,mod);show(page);}catch(Exception e){message(e.getMessage());}});p.add(b);p.add(Box.createVerticalStrut(8));}}catch(Exception e){line(p,e.getMessage());}p.add(button("导入本地模组 JAR","download",()->{if(busy)return;JFileChooser chooser=new JFileChooser();chooser.setMultiSelectionEnabled(true);if(chooser.showOpenDialog(frame)==JFileChooser.APPROVE_OPTION)try{Path dir=core.gameDir(i).resolve("mods");Files.createDirectories(dir);for(var f:chooser.getSelectedFiles()){if(!f.getName().endsWith(".jar"))throw new java.io.IOException("请选择 JAR");Files.copy(f.toPath(),Core.safe(dir,f.getName()));}show(page);}catch(Exception e){message(e.getMessage());}}));}
    void resources(JPanel p){JTextField query=new JTextField();JPanel results=transparent();results.setLayout(new BoxLayout(results,BoxLayout.Y_AXIS));row(p,"Modrinth 模组搜索",query);p.add(button("搜索兼容模组","download",()->{Core.Instance i=selected();if(i==null){message("请先选择实例");return;}String q=query.getText();run(()->{JsonArray hits=core.search(q,"mod",i.game());SwingUtilities.invokeLater(()->{results.removeAll();for(JsonElement e:hits){JsonObject hit=Core.obj(e);JButton b=button(Core.str(hit,"title","模组"),"mod",()->run(()->core.installMod(hit,i,this::message)));results.add(b);results.add(Box.createVerticalStrut(8));}results.revalidate();results.repaint();message("找到 "+hits.size()+" 项模组；点击下载安装");});});}));p.add(Box.createVerticalStrut(16));p.add(results);}
    void logs(JPanel p){JTextArea area=new JTextArea(15,55);area.setEditable(false);area.setFont(new Font(Font.MONOSPACED,Font.PLAIN,12));area.setBackground(new Color(247,253,251));try{area.setText(core.logTail());}catch(Exception e){area.setText(e.getMessage());}p.add(new JScrollPane(area));p.add(Box.createVerticalStrut(12));p.add(button("刷新日志","logs",()->show(page)));p.add(button("打开日志文件夹","folder",()->open(core.root.resolve("logs"))));}
    void settings(JPanel p){row(p,"内存 MB",ram);row(p,"窗口宽度",width);row(p,"窗口高度",height);p.add(button("保存当前实例设置","settings",()->{try{saveSettings();message("设置已保存");}catch(Exception e){message(e.getMessage());}}));line(p,"数据目录："+core.root);}
    public static final class Glass extends JPanel {
        final boolean card;Glass(boolean card){this.card=card;setOpaque(false);}
        protected void paintComponent(Graphics raw){Graphics2D g=(Graphics2D)raw.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);Color background=UIManager.getColor("Panel.background");if(background==null)background=new Color(245,245,247);g.setColor(background);if(card){g.fillRoundRect(0,0,getWidth()-1,getHeight()-1,22,22);g.setColor(new Color(128,128,128,45));g.drawRoundRect(0,0,getWidth()-1,getHeight()-1,22,22);}else g.fillRect(0,0,getWidth(),getHeight());g.dispose();super.paintComponent(raw);}

    }
    public static final class Glyph implements Icon {
        final String kind;final int size;public Glyph(String kind,int size){this.kind=kind;this.size=size;}public int getIconWidth(){return size;}public int getIconHeight(){return size;}
        public Image image(){var image=new java.awt.image.BufferedImage(size,size,java.awt.image.BufferedImage.TYPE_INT_ARGB);paintIcon(null,image.createGraphics(),0,0);return image;}
        public void paintIcon(Component c,Graphics raw,int x,int y){Graphics2D g=(Graphics2D)raw.create();g.translate(x,y);g.scale(size/40.0,size/40.0);g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setPaint(new GradientPaint(2,0,new Color(57,164,151),38,40,new Color(48,89,143)));g.fillRoundRect(1,1,38,38,12,12);g.setColor(new Color(255,255,255,135));g.drawRoundRect(2,2,36,36,11,11);g.setColor(Color.WHITE);g.setStroke(new BasicStroke(2.2f,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));switch(kind){case "grass"->{Path2D top=new Path2D.Double();top.moveTo(9,16);top.lineTo(20,10);top.lineTo(31,16);top.lineTo(20,23);top.closePath();g.setColor(new Color(196,244,151));g.fill(top);g.setColor(new Color(231,246,214));g.drawLine(9,17,9,27);g.drawLine(9,27,20,33);g.drawLine(20,33,31,27);g.drawLine(31,27,31,17);g.drawLine(20,24,20,32);}case "play"->{Path2D p=new Path2D.Double();p.moveTo(16,11);p.lineTo(29,20);p.lineTo(16,29);p.closePath();g.fill(p);}case "download"->{g.drawLine(20,10,20,25);g.drawLine(14,20,20,26);g.drawLine(20,26,26,20);g.drawLine(11,30,29,30);}case "versions"->{g.drawRoundRect(10,11,20,15,3,3);g.drawLine(13,30,27,30);g.drawLine(16,34,24,34);}case "mod"->{g.drawRoundRect(11,11,18,18,3,3);g.drawOval(16,8,7,7);g.drawLine(15,34,25,34);}case "logs"->{g.drawLine(10,27,15,20);g.drawLine(15,20,20,25);g.drawLine(20,25,24,13);g.drawLine(24,13,30,20);}case "settings"->{for(int n=0;n<3;n++){int yy=12+n*8;g.drawLine(10,yy,30,yy);g.fillOval((n==1?24:14)-3,yy-3,6,6);}}case "folder"->{g.drawRoundRect(10,15,21,15,3,3);g.drawLine(10,14,10,11);g.drawLine(10,11,18,11);}case "stop"->g.fillRoundRect(13,13,14,14,3,3);default->{g.drawOval(10,10,20,20);g.drawLine(20,18,20,26);g.fillOval(19,13,3,3);}}g.setPaint(new GradientPaint(0,1,new Color(255,255,255,100),0,24,new Color(255,255,255,0)));g.fillRoundRect(3,2,34,18,10,10);g.dispose();}
    }
    public static void main(String[] args){System.setProperty("awt.useSystemAAFontSettings","on");System.setProperty("swing.aatext","true");SwingUtilities.invokeLater(()->{try{UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());for(String font:new String[]{"Microsoft YaHei UI","PingFang SC","Noto Sans CJK SC","SansSerif"}){if(Arrays.asList(GraphicsEnvironment.getLocalGraphicsEnvironment().getAvailableFontFamilyNames()).contains(font)){Font f=new Font(font,Font.PLAIN,14);for(Object key:UIManager.getDefaults().keySet())if(UIManager.get(key) instanceof javax.swing.plaf.FontUIResource)UIManager.put(key,new javax.swing.plaf.FontUIResource(f));break;}}Launcher launcher=new Launcher();if(Arrays.asList(args).contains("--smoke")){javax.swing.Timer timer=new javax.swing.Timer(2500,event->{launcher.frame.dispose();System.out.println("PASS: desktop window constructed and closed");});timer.setRepeats(false);timer.start();}}catch(Exception e){if(Arrays.asList(args).contains("--smoke")){e.printStackTrace();System.exit(1);}JOptionPane.showMessageDialog(null,e.toString(),"GCL 启动失败",JOptionPane.ERROR_MESSAGE);}});}
}
